// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice Signature validation utilities.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/SignatureCheckerLib.sol)
library SignatureCheckerLib {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         CONSTANTS                          */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev `keccak256("isValidSignature(bytes32,bytes)")`.
    uint256 private constant _ERC1271_MAGIC_VALUE = 0x1626ba7e;

    /// @dev `0x6492649264926492649264926492649264926492649264926492649264926492`.
    uint256 private constant _ERC6492_MAGIC_VALUE =
        0x6492649264926492649264926492649264926492649264926492649264926492;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                 SIGNATURE CHECKER FUNCTIONS                */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Validates if a given signature is valid for a specific signer and hash.
    function isValidSignatureNow(address signer, bytes32 hash, bytes memory signature)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40) // Cache the free memory pointer.
            for {} 1 {} {
                if iszero(signer) { break }
                // Direct ECDSA validation.
                let t := mload(signature)
                switch t
                case 64 {
                    let vs := mload(add(signature, 0x40))
                    mstore(0x20, add(shr(255, vs), 27)) // `v`.
                    mstore(0x60, shr(1, shl(1, vs))) // `s`.
                }
                case 65 {
                    mstore(0x20, byte(0, mload(add(signature, 0x60)))) // `v`.
                    mstore(0x60, mload(add(signature, 0x40))) // `s`.
                }
                default {
                    // Not a standard ECDSA signature, try ERC1271.
                    isValid := _isValidERC1271SignatureNow(signer, hash, add(signature, 0x20), t)
                    break
                }
                mstore(0x00, hash)
                mstore(0x40, mload(add(signature, 0x20))) // `r`.
                let v := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
                mstore(0x60, 0) // Restore the zero slot.
                mstore(0x40, m) // Restore the free memory pointer.
                if and(v, eq(mload(0x00), signer)) {
                    isValid := 1
                    break
                }
                // Try ERC1271 if direct ECDSA recovery didn't match.
                isValid := _isValidERC1271SignatureNow(signer, hash, add(signature, 0x20), t)
                break
            }
        }
    }

    /// @notice Validates a signature for a given hash using the provided signer and signature.
    function isValidSignatureNowCalldata(address signer, bytes32 hash, bytes calldata signature)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40) // Cache the free memory pointer.
            for {} 1 {} {
                if iszero(signer) { break }
                // Direct ECDSA validation.
                let t := signature.length
                switch t
                case 64 {
                    let vs := calldataload(add(signature.offset, 0x20))
                    mstore(0x20, add(shr(255, vs), 27)) // `v`.
                    mstore(0x40, calldataload(signature.offset)) // `r`.
                    mstore(0x60, shr(1, shl(1, vs))) // `s`.
                }
                case 65 {
                    mstore(0x20, byte(0, calldataload(add(signature.offset, 0x40)))) // `v`.
                    calldatacopy(0x40, signature.offset, 0x40) // Copy `r` and `s`.
                }
                default {
                    // Not a standard ECDSA signature, try ERC1271.
                    isValid := _isValidERC1271SignatureNowCalldata(signer, hash, signature.offset, t)
                    break
                }
                mstore(0x00, hash)
                let v := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
                mstore(0x60, 0) // Restore the zero slot.
                mstore(0x40, m) // Restore the free memory pointer.
                if and(v, eq(mload(0x00), signer)) {
                    isValid := 1
                    break
                }
                // Try ERC1271 if direct ECDSA recovery didn't match.
                isValid := _isValidERC1271SignatureNowCalldata(signer, hash, signature.offset, t)
                break
            }
        }
    }

    /// @notice Validates if a given signature is valid for a specific signer and hash.
    function isValidSignatureNow(address signer, bytes32 hash, bytes32 r, bytes32 vs)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            if iszero(signer) { return(0, 0x20) }
            let m := mload(0x40) // Cache the free memory pointer.
            mstore(0x00, hash)
            mstore(0x20, add(shr(255, vs), 27)) // `v`.
            mstore(0x40, r)
            mstore(0x60, shr(1, shl(1, vs))) // `s`.
            let v := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
            mstore(0x60, 0) // Restore the zero slot.
            mstore(0x40, m) // Restore the free memory pointer.
            if and(v, eq(mload(0x00), signer)) {
                isValid := 1
            }
        }
    }

    /// @notice Validates if a given signature is valid for a specific signer and hash.
    function isValidSignatureNow(address signer, bytes32 hash, uint8 v, bytes32 r, bytes32 s)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            if iszero(signer) { return(0, 0x20) }
            let m := mload(0x40) // Cache the free memory pointer.
            mstore(0x00, hash)
            mstore(0x20, and(v, 0xff))
            mstore(0x40, r)
            mstore(0x60, s)
            let w := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
            mstore(0x60, 0) // Restore the zero slot.
            mstore(0x40, m) // Restore the free memory pointer.
            if and(w, eq(mload(0x00), signer)) {
                isValid := 1
            }
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                  ERC1271 SIGNATURE CHECKER                 */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Checks if a given signature is valid for a specific signer and hash according to the ERC1271 standard.
    function isValidERC1271SignatureNow(address signer, bytes32 hash, bytes memory signature)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x00, 0x1626ba7e) // `isValidSignature(bytes32,bytes)`.
            mstore(0x20, hash)
            mstore(0x40, 0x40)
            let t := mload(signature)
            mstore(0x60, t)
            calldatacopy(0x80, add(signature, 0x20), t)
            let d := add(0x80, t) // Total size of the call data.
            let w := mload(staticcall(gas(), signer, 0x1c, sub(d, 0x1c), 0x00, 0x20))
            mstore(0x40, m) // Restore the free memory pointer.
            mstore(0x60, 0) // Restore the zero slot.
            // Whether the staticcall succeeds, and the returned data is the magic value.
            isValid := and(w, and(eq(mload(0x00), _ERC1271_MAGIC_VALUE), eq(returndatasize(), 0x20)))
        }
    }

    /// @notice Validates an ERC1271 signature using calldata.
    function isValidERC1271SignatureNowCalldata(address signer, bytes32 hash, bytes calldata signature)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x00, 0x1626ba7e) // `isValidSignature(bytes32,bytes)`.
            mstore(0x20, hash)
            mstore(0x40, 0x40)
            mstore(0x60, signature.length)
            calldatacopy(0x80, signature.offset, signature.length)
            let d := add(0x80, signature.length) // Total size of the call data.
            let w := mload(staticcall(gas(), signer, 0x1c, sub(d, 0x1c), 0x00, 0x20))
            mstore(0x40, m) // Restore the free memory pointer.
            mstore(0x60, 0) // Restore the zero slot.
            // Whether the staticcall succeeds, and the returned data is the magic value.
            isValid := and(w, and(eq(mload(0x00), _ERC1271_MAGIC_VALUE), eq(returndatasize(), 0x20)))
        }
    }

    /// @notice Checks if a given signature is valid for a specific signer and hash according to the ERC1271 standard.
    function isValidERC1271SignatureNow(address signer, bytes32 hash, bytes32 r, bytes32 vs)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x00, 0x1626ba7e) // `isValidSignature(bytes32,bytes)`.
            mstore(0x20, hash)
            mstore(0x40, 0x40)
            mstore(0x60, 0x40)
            mstore(0x80, r)
            mstore(0xa0, vs)
            let w := mload(staticcall(gas(), signer, 0x1c, 0xa4, 0x00, 0x20))
            mstore(0x40, m) // Restore the free memory pointer.
            mstore(0x60, 0) // Restore the zero slot.
            // Whether the staticcall succeeds, and the returned data is the magic value.
            isValid := and(w, and(eq(mload(0x00), _ERC1271_MAGIC_VALUE), eq(returndatasize(), 0x20)))
        }
    }

    /// @notice Checks if a given signature is valid for a specific signer and hash according to the ERC1271 standard.
    function isValidERC1271SignatureNow(address signer, bytes32 hash, uint8 v, bytes32 r, bytes32 s)
        internal
        view
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x00, 0x1626ba7e) // `isValidSignature(bytes32,bytes)`.
            mstore(0x20, hash)
            mstore(0x40, 0x40)
            mstore(0x60, 0x41)
            mstore(0x80, r)
            mstore(0xa0, s)
            mstore(0xc0, and(v, 0xff))
            let w := mload(staticcall(gas(), signer, 0x1c, 0xc4, 0x00, 0x20))
            mstore(0x40, m) // Restore the free memory pointer.
            mstore(0x60, 0) // Restore the zero slot.
            // Whether the staticcall succeeds, and the returned data is the magic value.
            isValid := and(w, and(eq(mload(0x00), _ERC1271_MAGIC_VALUE), eq(returndatasize(), 0x20)))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                  ERC6492 SIGNATURE CHECKER                 */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Validates an ERC6492 signature with side effects allowed.
    function isValidERC6492SignatureNowAllowSideEffects(address signer, bytes32 hash, bytes memory signature)
        internal
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            let n := mload(signature)
            // Check if the signature ends with the ERC6492 magic value.
            let o := add(signature, n)
            if eq(mload(sub(o, 0x20)), _ERC6492_MAGIC_VALUE) {
                // ERC6492 wrapped signature format:
                // [factory address (20)] [factory calldata (dynamic)] [original signature (dynamic)] [magic (32)]
                // The offset to the original signature is at the start of the signature.
                let s := add(signature, 0x20)
                let d := mload(s)
                // Extract the factory address and calldata.
                let factory := mload(add(s, 0x20))
                let factoryCalldataOffset := add(s, mload(add(s, 0x40)))
                let factoryCalldataLength := mload(factoryCalldataOffset)
                // Call the factory to deploy/initialize the contract.
                pop(call(gas(), factory, 0, add(factoryCalldataOffset, 0x20), factoryCalldataLength, 0, 0))
                // Extract the original signature.
                let sigOffset := add(s, d)
                let sigLength := mload(sigOffset)
                // Try ERC1271 with the original signature.
                mstore(0x00, 0x1626ba7e) // `isValidSignature(bytes32,bytes)`.
                mstore(0x20, hash)
                mstore(0x40, 0x40)
                mstore(0x60, sigLength)
                mstore(0x80, 0) // Zero out for safety.
                calldatacopy(0x80, add(sigOffset, 0x20), sigLength)
                let w := mload(staticcall(gas(), signer, 0x1c, add(0x64, sigLength), 0x00, 0x20))
                isValid := and(w, and(eq(mload(0x00), _ERC1271_MAGIC_VALUE), eq(returndatasize(), 0x20)))
                mstore(0x40, m) // Restore the free memory pointer.
                mstore(0x60, 0) // Restore the zero slot.
                return(isValid, 0x20)
            }
            // Not an ERC6492 signature, fall through to regular validation.
        }
        isValid = isValidSignatureNow(signer, hash, signature);
    }

    /// @notice Validates an ERC6492 signature by checking if it matches the provided signer and hash.
    function isValidERC6492SignatureNow(address signer, bytes32 hash, bytes memory signature)
        internal
        returns (bool isValid)
    {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            let n := mload(signature)
            // Check if the signature ends with the ERC6492 magic value.
            let o := add(signature, n)
            if eq(mload(sub(o, 0x20)), _ERC6492_MAGIC_VALUE) {
                // ERC6492 wrapped signature format:
                // [factory address (20)] [factory calldata (dynamic)] [original signature (dynamic)] [magic (32)]
                let s := add(signature, 0x20)
                let d := mload(s)
                // Extract the factory address and calldata.
                let factory := mload(add(s, 0x20))
                let factoryCalldataOffset := add(s, mload(add(s, 0x40)))
                let factoryCalldataLength := mload(factoryCalldataOffset)
                // Call the factory to deploy/initialize the contract.
                let deploySuccess := call(gas(), factory, 0, add(factoryCalldataOffset, 0x20), factoryCalldataLength, 0, 0)
                // Extract the original signature.
                let sigOffset := add(s, d)
                let sigLength := mload(sigOffset)
                // Try ERC1271 with the original signature.
                mstore(0x00, 0x1626ba7e) // `isValidSignature(bytes32,bytes)`.
                mstore(0x20, hash)
                mstore(0x40, 0x40)
                mstore(0x60, sigLength)
                calldatacopy(0x80, add(sigOffset, 0x20), sigLength)
                let w := mload(staticcall(gas(), signer, 0x1c, add(0x64, sigLength), 0x00, 0x20))
                mstore(0x40, m) // Restore the free memory pointer.
                mstore(0x60, 0) // Restore the zero slot.
                isValid := and(w, and(eq(mload(0x00), _ERC1271_MAGIC_VALUE), eq(returndatasize(), 0x20)))
                return(isValid, 0x20)
            }
            // Not an ERC6492 signature.
            mstore(0x40, m) // Restore the free memory pointer.
        }
        isValid = isValidSignatureNow(signer, hash, signature);
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     HASHING OPERATIONS                     */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Converts a bytes32 hash into an Ethereum signed message hash.
    function toEthSignedMessageHash(bytes32 hash) internal pure returns (bytes32 result) {
        /// @solidity memory-safe-assembly
        assembly {
            mstore(0x20, hash) // Store into scratch space for keccak256.
            mstore(0x00, "\x00\x00\x00\x00\x19Ethereum Signed Message:\n32") // 28 bytes.
            result := keccak256(0x04, 0x3c) // `32 * 2 - (32 - 28) = 60 = 0x3c`.
        }
    }

    /// @notice Converts a bytes32 hash into an Ethereum signed message hash.
    function toEthSignedMessageHash(bytes memory s) internal pure returns (bytes32 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let sLength := mload(s)
            let o := 0x20
            mstore(o, "\x19Ethereum Signed Message:\n") // 26 bytes, zero-right-padded.
            mstore(0x00, 0x00)
            // Convert the `s.length` to ASCII decimal representation: `base10(s.length)`.
            for { let temp := sLength } 1 {} {
                o := sub(o, 1)
                mstore8(o, add(48, mod(temp, 10)))
                temp := div(temp, 10)
                if iszero(temp) { break }
            }
            let n := sub(0x3a, o) // Header length: `26 + 32 - o`.
            // Throw an out-of-offset error (consumes all gas) if the header exceeds 32 bytes.
            returndatacopy(returndatasize(), returndatasize(), gt(n, 0x20))
            mstore(s, or(mload(0x00), mload(n))) // Temporarily store the header.
            result := keccak256(add(s, sub(0x20, n)), add(n, sLength))
            mstore(s, sLength) // Restore the length.
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                   EMPTY CALLDATA HELPERS                   */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Returns an empty signature in the form of a `bytes calldata` object.
    function emptySignature() internal pure returns (bytes calldata signature) {
        /// @solidity memory-safe-assembly
        assembly {
            signature.length := 0
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                   INTERNAL HELPERS                         */
